        node_cache_match is not None,
        "Kagemusha payload workflow must cache JavaScript SDK dependencies by package-lock",
        errors,
    )
    require(
        install_match is not None,
        "Kagemusha payload workflow must install JavaScript SDK dependencies",
        errors,
    )
    require(
        native_build_match is not None,
        "Kagemusha payload workflow must build the JavaScript SDK native host",
        errors,
    )
    require(
        test_match is not None,
        "Kagemusha payload workflow must run the JavaScript recursive spend SDK tests",
        errors,
    )
    if setup_match is not None and install_match is not None:
        require(
            setup_match.start() < install_match.start(),
            "Kagemusha payload workflow must set up Node before installing JavaScript SDK dependencies",
            errors,
        )
    if install_match is not None and test_match is not None:
        require(
            install_match.start() < test_match.start(),
            "Kagemusha payload workflow must install JavaScript SDK dependencies before running JavaScript tests",
            errors,
        )
    if install_match is not None and native_build_match is not None:
        require(
            install_match.start() < native_build_match.start(),
            "Kagemusha payload workflow must install JavaScript SDK dependencies before building the native host",
            errors,
        )
    if native_build_match is not None and test_match is not None:
        require(
            native_build_match.start() < test_match.start(),
            "Kagemusha payload workflow must build the JavaScript SDK native host before running JavaScript tests",
            errors,
        )
    require(
        JS_SDK_JOB in benchmark_needs,
        "Kagemusha payload benchmark job must wait for the JavaScript SDK test job",
        errors,
    )


def check_javascript_sdk_script(errors):
    script = read(JS_SDK_TEST_COMMAND)
    require(
        'NODE_OVERRIDE="${KAGEMUSHA_RECURSIVE_SPEND_JS_SDK_NODE_BIN:-}"' in script,
        "Kagemusha JavaScript SDK script must keep the documented Node override variable",
        errors,
    )
    require(
        "resolve_node_20_bin()" in script and "is_node_20_bin()" in script,
        "Kagemusha JavaScript SDK script must resolve Node 20 before falling back to node",
        errors,
    )
    require(
        'NODE_BIN="$(resolve_node_20_bin)"' in script,
        "Kagemusha JavaScript SDK script must use the Node 20 resolver",
        errors,
    )
    require(
        'NODE_VERSION="$("${NODE_BIN}" --version)"' in script,
        "Kagemusha JavaScript SDK script must print the selected Node version",
        errors,
    )
    require(
        'printf \'%s\\n\' "${NODE_VERSION}"' in script,
        "Kagemusha JavaScript SDK script must emit the selected Node version",
        errors,
    )
    require(
        "v20.*) ;;" in script,
        "Kagemusha JavaScript SDK script must reject non-Node-20 runtimes",
        errors,
    )
    require(
        "native_binding_is_ready()" in script
        and 'NATIVE_BINDING_PROBE_QUIET="${quiet}" "${NODE_BIN}" --input-type=module' in script
        and 'native_binding_is_ready quiet' in script
        and 'const quiet = process.env.NATIVE_BINDING_PROBE_QUIET === "quiet";' in script
        and "verifyNativeBinding(bindingPath, { manifestPath })" in script
        and 'if [[ -n "${IROHA_JS_NATIVE_DIR:-}" ]]; then' in script,
        "Kagemusha JavaScript SDK script must verify explicit native binding overrides before tests",
        errors,
    )
    require(
        "prepare_native_binding()" in script
        and 'TEMP_NATIVE_DIR="$(mktemp -d "${TMPDIR:-/tmp}/iroha-js-native-kagemusha.XXXXXX")"' in script
        and 'IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}" "${NODE_BIN}" ./scripts/build-native.mjs' in script
        and 'IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}" "${NODE_BIN}" ./scripts/copy-native.mjs' in script
        and 'export IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}"' in script,
        "Kagemusha JavaScript SDK script must prepare a verified temporary native binding when repo artifacts are stale",
        errors,
    )
    require(
        "cleanup_temp_native_dir()" in script
        and "trap cleanup_temp_native_dir EXIT" in script,
        "Kagemusha JavaScript SDK script must clean up temporary native build artifacts",
        errors,
    )
    prepare_call = script.find("\nprepare_native_binding\n")
    test_call = script.find('\n"${NODE_BIN}" --test ')
    require(
        prepare_call != -1 and test_call != -1 and prepare_call < test_call,
        "Kagemusha JavaScript SDK script must prepare a verified native binding before running tests",
