def check_python(texts, errors):
    script = read(PYTHON_SDK_TEST_COMMAND)
    require(
        'PYTHON_OVERRIDE="${KAGEMUSHA_RECURSIVE_SPEND_PYTHON_BIN:-}"' in script,
        "Kagemusha Python SDK script must keep the documented Python override variable",
        errors,
    )
    require(
        "resolve_python_311_bin()" in script and "python3.11" in script,
        "Kagemusha Python SDK script must resolve Python 3.11 before falling back to python3",
        errors,
    )
    require(
        'PYTHON_BIN="$(resolve_python_311_bin)"' in script,
        "Kagemusha Python SDK script must use the Python 3.11 resolver",
        errors,
    )
    require(
        'PYTHON_VERSION="$("${PYTHON_BIN}" -c' in script,
        "Kagemusha Python SDK script must capture the selected Python version",
        errors,
    )
    require(
        '"${PYTHON_BIN}" --version' in script,
        "Kagemusha Python SDK script must print the selected Python version",
        errors,
    )
    require(
        'VENV_PYTHON_VERSION="$("${VENV_DIR}/bin/python" -c' in script,
        "Kagemusha Python SDK script must capture the venv Python version",
        errors,
    )
    require(
        script.count('"${VENV_DIR}/bin/python" --version') >= 2,
        "Kagemusha Python SDK script must print the initial and rebuilt venv Python versions",
        errors,
    )
    require(
        "3.11) ;;" in script,
        "Kagemusha Python SDK script must reject non-Python-3.11 runtimes",
        errors,
    )
    require(
        "recreating Kagemusha recursive spend Python SDK venv" in script,
        "Kagemusha Python SDK script must rebuild stale non-3.11 venvs",
        errors,
    )
    require(
        'rm -rf "${VENV_DIR}"' in script,
        "Kagemusha Python SDK script must remove stale venvs before rebuilding",
        errors,
    )
    require(
        "'maturin>=1.5,<2'" in script,
        "Kagemusha Python SDK script must install maturin for native extension builds",
        errors,
    )
    require(
        '"${VENV_DIR}/bin/python" -m pip install --no-deps' in script
        and '"${ROOT_DIR}/python/norito_py"' in script
        and '"${ROOT_DIR}/python/iroha_torii_client"' in script,
        "Kagemusha Python SDK script must install local workspace Python packages before maturin",
        errors,
    )
    require(
        'export VIRTUAL_ENV="${VENV_DIR}"' in script
        and 'export PATH="${VENV_DIR}/bin:${PATH}"' in script,
        "Kagemusha Python SDK script must activate the selected venv before maturin",
        errors,
    )
    require(
        '"${VENV_DIR}/bin/python" -m maturin develop --release' in script,
        "Kagemusha Python SDK script must build the native extension with the selected Python",
        errors,
    )
    abi7_fixture_guard_index = script.find(PYTHON_ABI7_FIXTURE_NATIVE_GUARD_COMMAND)
    python_confidential_diversifier_guard_index = script.find(
        PYTHON_CONFIDENTIAL_INPUT_DIVERSIFIER_NATIVE_GUARD_COMMAND
    )
    maturin_index = script.find('"${VENV_DIR}/bin/python" -m maturin develop --release')
    require(
        abi7_fixture_guard_index >= 0,
        "Kagemusha Python SDK script must run the ABI-7 archive fixture native guard",
        errors,
    )
    if abi7_fixture_guard_index >= 0 and maturin_index >= 0:
        require(
            abi7_fixture_guard_index < maturin_index,
            "Kagemusha Python SDK script must validate ABI-7 archive fixtures before building the wheel",
            errors,
        )
    require(
        python_confidential_diversifier_guard_index >= 0,
        "Kagemusha Python SDK script must run the confidential input diversifier native guard",
        errors,
    )
    if python_confidential_diversifier_guard_index >= 0 and maturin_index >= 0:
        require(
            python_confidential_diversifier_guard_index < maturin_index,
            "Kagemusha Python SDK script must validate confidential input diversifiers before building the wheel",
            errors,
        )
    require(
        "export PYTHONDONTWRITEBYTECODE=1" in script,
        "Kagemusha Python SDK script must not write bytecode cache files during tests",
        errors,
    )
    for test_path in (
        "tests/kagemusha_test.py",
        "tests/privacy_catalog_test.py",
        "tests/crypto_algorithms_test.py",
        "tests/test_nexus_app.py",
        "tests/offline_cash_test.py",
        "tests/testconnect_codec.py",
        "tests/test_address_format.py",
    ):
        require(
            test_path in script,
            f"Kagemusha Python SDK script must run {test_path}",
            errors,
        )
    require(
        "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_canonical_request_auth_rejects_padded_fields_before_send" in script,
        "Kagemusha Python SDK script must run the Torii canonical request auth exactness regression",
        errors,
    )
    require(
        "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_call_contract_rejects_padded_selectors_before_dispatch" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_submit_bridge_proof_rejects_padded_signing_fields_before_request" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_submit_bridge_message_rejects_padded_signing_fields_before_request" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_uaid_portfolio_rejects_padded_literal_before_dispatch" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_uaid_portfolio_rejects_padded_asset_id_before_dispatch" in script,
        "Kagemusha Python SDK script must run Torii query selector, bridge submit, and UAID path literal exactness regressions",
        errors,
    )
    require(
        "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_identifier_resolution_receipt_matches_shared_vectors" in script,
        "Kagemusha Python SDK script must run the identifier receipt exactness and adversarial vector regression",
        errors,
    )
    require(
        "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_propose_multisig_rejects_malformed_response_fields" in script,
        "Kagemusha Python SDK script must run the multisig resolved account exactness regression",
        errors,
    )
    require(
        "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_offline_readiness_parses_payload" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_offline_readiness_rejects_noncanonical_abi_versions" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_offline_readiness_rejects_removed_abi7_fields" in script
        and "${ROOT_DIR}/python/iroha_torii_client/tests/test_client.py::test_get_offline_readiness_rejects_missing_recursive_compact_family" in script,
        "Kagemusha Python SDK script must run Torii offline readiness ABI exactness regressions",
        errors,
    )
    require(
        "tests/client_ledger_helpers_test.py" in script
        and "zk_event_filters_reject_unsupported_backends_before_request" in script
        and "zk_verifying_key_event_filters_reject_malformed_names_before_request" in script
        and "zk_proof_event_filters_reject_malformed_hashes_before_request" in script
        and "zk_raw_event_filters_reject_malformed_privacy_matchers_before_request" in script
        and "zk_raw_event_filters_canonicalize_privacy_matchers_before_request" in script,
        "Kagemusha Python SDK script must run Torii event-filter verifier/proof exactness regressions",
        errors,
    )
    require_contains(
        texts,
        "python/iroha_torii_client/client.py",
        (
            'params["asset_id"] = _require_exact_non_empty_string(',
            '"uaid portfolio asset_id"',
            '"contract_address": _require_exact_non_empty_string(',
            '"contract_alias": _require_exact_non_empty_string(',
