    require_contains(
        texts,
        "python/iroha_torii_client/tests/test_client.py",
        (
            "test_call_contract_rejects_padded_selectors_before_dispatch",
            "test_get_uaid_portfolio_rejects_padded_asset_id_before_dispatch",
