        "Python append output selector alias boundary",
        errors,
    )
    require_contains(
        texts,
        wrapper,
        REQUIRED_LINEAGE_KEY_ARTIFACT_PYTHON_ALL_PUBLIC_METHODS
        + (
            "@dataclass(frozen=True)",
            "is_init_artifact",
            "is_append_artifact",
            "_validate_kagemusha_recursive_spend_lineage_key_artifact_package_binding",
