def check_sdk_readme_previous_proof_boundary(texts, errors):
    required = (
        "previous_recursive_proof_open_envelopes_archive",
        "opaque native prover material",
        "must not construct, rewrite, or mutate",
        "vk_commitment",
        "public_inputs_schema_hash",
        "domain_tag",
        "against the exact previous bundle",
        "the append-boundary helper",
        "append-boundary digest uses the public",
        "chain/asset and final-root/current-note binding",
        "semantic previous bundles keep using semantic append",
        "plus a record-backed lineage witness",
        "previous recursive proof bytes",
        "`recursive_proof_chain_digest`",
        "native-owned accumulator digests",
        "lineage/aggregation transcript",
        "fixed-window schedule/shared-manifest/table-base",
        "verifier-witness batch",
        "transition-profile",
        "append-opening-preflight",
        "append-boundary",
        "scalar-projection",
        "previous/resulting accumulator digests",
        "must not derive, supply, or patch accumulator state",
    )
    for relative in SDK_README_PATHS:
        text = re.sub(r"\s+", " ", texts[relative])
        for needle in required:
            require(
                needle in text,
                f"{relative} missing previous-proof opening archive boundary: {needle}",
                errors,
            )
        for needle in SDK_NATIVE_MATERIAL_README_NEEDLES:
            require(
                needle in text,
                f"{relative} missing native material alias README boundary: {needle}",
                errors,
            )
        request_field_needle = SDK_NATIVE_MATERIAL_README_REQUEST_FIELD_NEEDLES[relative]
        require(
            request_field_needle in text,
            f"{relative} missing native material alias README request-field boundary: {request_field_needle}",
            errors,
        )
        if relative in NON_CSHARP_SDK_README_PATHS:
            for needle in NON_CSHARP_REDEEM_LINEAGE_RECORD_README_NEEDLES:
                require(
                    needle in text,
                    f"{relative} missing redeem lineage verifier-record README boundary: {needle}",
                    errors,
                )
        require(
            "Future Reserved-lineage append output" not in text,
            f"{relative} still describes Reserved-lineage append output as future",
            errors,
        )
        require(
            "legacy single" not in text,
            f"{relative} still describes redeem lineage verifier-record README boundary as legacy single",
            errors,
        )
        require(
            "legacy `lineage_verifier_record`" not in text
            and "legacy\n`lineage_verifier_record`" not in text
            and "single-record path remains supported" not in text,
            f"{relative} still describes redeem lineage verifier-record README boundary as legacy single-record compatibility",
            errors,
        )
        require(
            "Newer redeem request archives" not in text,
            f"{relative} still describes redeem lineage verifier-record README boundary as older/newer compatibility",
            errors,
        )


def public_kagemusha_readiness_doc_paths():
    paths = set(SDK_README_PATHS)
    for root_relative in PUBLIC_KAGEMUSHA_READINESS_DOC_ROOTS:
        base = root / root_relative
        if not base.exists():
            continue
        for path in base.rglob("*.md"):
            if root_relative == "docs/portal/i18n" and "sdks" not in path.parts:
                continue
            paths.add(path.relative_to(root).as_posix())
    return sorted(paths)


def check_public_docs_removed_kagemusha_readiness_aliases(texts, errors):
    for relative in public_kagemusha_readiness_doc_paths():
        if relative in texts:
            text = texts[relative]
        else:
            path = root / relative
            if not path.exists():
                continue
            text = read(relative)
        require(
            REMOVED_KAGEMUSHA_READINESS_ALIAS not in text,
            (
                f"{relative} must not publish removed {REMOVED_KAGEMUSHA_READINESS_ALIAS} "
                f"readiness alias; use {CANONICAL_KAGEMUSHA_READINESS_FIELD}"
            ),
            errors,
        )


