def check_abi7_sdk_manifest_coverage(_texts, errors):
    for relative, needles in ABI7_SDK_MANIFEST_COVERAGE.items():
        text = read(relative)
        for needle in needles:
            require(
                needle in text,
                f"ABI-7 SDK fixture manifest coverage missing {relative}: {needle}",
                errors,
            )


